#' RD Multiple Cutoffs
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param cutVar .
#' @param treatment .
#' @param p .
#' @param bwselect .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
rdmc <- function(
    data,
    outcome,
    running,
    cutVar,
    treatment,
    p = 1,
    bwselect = "mserd",
    kernel = "triangular",
    vce = "nn",
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdmc requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(cutVar), cutVar, NULL),
            `if`( ! missing(treatment), treatment, NULL))


    options <- rdmcOptions$new(
        outcome = outcome,
        running = running,
        cutVar = cutVar,
        treatment = treatment,
        p = p,
        bwselect = bwselect,
        kernel = kernel,
        vce = vce,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdmcClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

